import React, { useEffect, useState } from 'react';
import PriceTrendChart from './PriceTrendChart';
import SellingTrendChart from './SellingTrendChart';
import ProductDetailsInventory from './ProductDetailsInventory';
import './productDetails.css';
import { getProducts } from '../data/dataFetching';

import { useParams } from 'react-router-dom';

function ProductDetails() {

    const { id } = useParams();

    const [products, setProducts] = useState([]);

    useEffect(() => {
        getProducts().then(data => setProducts(data.filter((item) => item.id == id)));
    }, []);


    return (
        <div className="product-details">

            {products.map(products => (
                <>
                    <div className='general-info' key={products.id}> {/* should show only details about product that choose user */}
                        <h1>{products.name}</h1>
                        <i className={products.product_picture}></i>
                    </div>

                    <div className='price-info' key={products.id}>
                                        
                        <section>
                            <h4>Buy Price:</h4>
                            <h5>{products.buy_price}</h5>
                        </section>
                        <section>
                            <h4>Sell Price:</h4>
                            <h5>{products.sell_price}</h5>
                        </section>
                    </div>
                </>
            ))}

            

            <div className='product-location'>

                <h3>Warehouse Inventory</h3>
                <div className="table-container">
                    <ProductDetailsInventory />
                </div>

            </div>

            <div className='charts-holder'>


                <div className='chart-info mb-5'>

                    <h3>Selling Trend</h3>

                    <SellingTrendChart />


                </div>

                <div className='chart-info mb-5'>

                    <h3>Price Trend</h3>

                    <PriceTrendChart />


                </div>

            </div>


        </div>

    )
}

export default ProductDetails;
